-- Biochemistry Ch3: Non-enzymatic Protein Function & Protein Analysis — Batch 1 — Cellular Functions & Bio-Signaling
-- Original Praxist Prep questions, grounded in LibreTexts Biochemistry; scope verified vs AAMC 2026 outline.
-- Idempotent: deletes only this batch's subtopics, then re-inserts. question_attempts / distractor_metadata cascade.

DELETE FROM questions WHERE topic = 'Non-enzymatic Protein Function and Protein Analysis' AND subtopic IN ('Binding Proteins', 'G Protein-Coupled Receptors', 'Immunoglobulins', 'Ion Channels', 'Motor Proteins', 'Receptor Enzymes');

-- Q1 [Motor Proteins] hard skill2 ans=A
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES ('bio_biochem', 'Non-enzymatic Protein Function and Protein Analysis', 'Motor Proteins', 'A researcher studies vesicle trafficking in a cultured neuron whose axonal microtubules are oriented with their plus ends directed toward the distal axon terminal. She applies a compound that locks the motor protein kinesin onto the microtubule lattice after each round of ATP hydrolysis, so that the affected motor can no longer release from the track and take another step. Assuming dynein activity is unchanged, which movement is most likely to be selectively impaired in the treated neuron?', '[{"label": "A", "text": "Delivery of newly synthesized synaptic vesicles from the cell body outward to the distal axon terminal"}, {"label": "B", "text": "Return of aged membrane components from the distal axon terminal back toward the cell body"}, {"label": "C", "text": "Retrograde movement of endosomes from the axon terminal toward the perinuclear region"}, {"label": "D", "text": "Repositioning of the mitotic spindle as duplicated chromosomes are pulled toward opposite poles"}]'::jsonb, 'A', 'This is a Biochemistry question that falls under the content category ''Structure and Function of Proteins and Their Constituent Amino Acids.'' The answer is A because kinesin is the motor that hauls cargo toward the microtubule plus end, and in an axon whose plus ends point distally, that means anterograde transport of cargo such as synaptic vesicles from the cell body outward to the terminal—the exact process lost when kinesin can no longer detach and step. (Choice A) is correct: kinesin carries cargo toward the (+) end of microtubules; because the axon''s plus ends face the terminal, plus-end-directed (anterograde) delivery of vesicles from the cell body to the distal terminal is the kinesin-dependent process that a motor trapped on the track can no longer perform. (Choice B) is incorrect: this reflects the misconception that kinesin drives (−)-end-directed transport; movement from the terminal back toward the cell body is toward the (−) end and is carried by dynein, whose activity is stated to be unchanged. (Choice C) is incorrect: retrograde movement toward the perinuclear region is (−)-end-directed and is a dynein function, not kinesin''s, so it is spared; this option confuses which motor is minus-end-directed. (Choice D) is incorrect: while some kinesin-related proteins and spindle motors act in mitosis, a differentiated neuron is post-mitotic and has no mitotic spindle, so this process is not present to be impaired—it is an irrelevant, out-of-context application of motor function. This is a Scientific Reasoning and Problem Solving question because you must apply the directional roles of kinesin (plus-end/anterograde) and dynein (minus-end/retrograde) to a defined microtubule orientation and predict which specific cargo movement fails when kinesin is trapped on the track.', 'hard', '1A', 'Structure and Function of Proteins and Their Constituent Amino Acids', 'biochemistry', 2, 100)
  RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
  SELECT id, 'B', 'reversed_relationship', 'assigns kinesin the minus-end/retrograde direction that actually belongs to dynein' FROM q
  UNION ALL
  SELECT id, 'C', 'reversed_relationship', 'confuses which motor is minus-end-directed, attributing retrograde perinuclear transport to kinesin' FROM q
  UNION ALL
  SELECT id, 'D', 'adjacent_fact', 'invokes a real but context-inappropriate motor role (mitotic spindle) in a post-mitotic neuron' FROM q;

-- Q2 [Motor Proteins] easy skill1 ans=A
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES ('bio_biochem', 'Non-enzymatic Protein Function and Protein Analysis', 'Motor Proteins', 'A cell biologist treats cultured fibroblasts with a drug that selectively and completely depolymerizes microtubules while leaving actin filaments fully intact. The researcher then tracks the movement of several fluorescently labeled cargoes, each carried by a different type of motor protein. For which cargo does directed transport MOST LIKELY continue after the treatment?', '[{"label": "A", "text": "The cargo carried by myosin, which continues moving along the intact filaments"}, {"label": "B", "text": "The cargo carried by kinesin, which continues moving along the intact filaments"}, {"label": "C", "text": "The cargo carried by dynein, which continues moving along the intact filaments"}, {"label": "D", "text": "None of the cargoes, because every motor protein has lost its track for movement"}]'::jsonb, 'A', 'This is a Biochemistry question that falls under the content category ''Structure and Function of Proteins and Their Constituent Amino Acids.'' The answer is A because myosin moves along actin filaments, which remain intact, whereas kinesin and dynein both require microtubules, which have been depolymerized. (Choice A) is correct: myosin is the actin-based motor, so its cargo continues to be transported along the still-intact actin filaments after microtubules are destroyed. (Choice B) is incorrect: this reflects the misconception that kinesin uses actin; kinesin is a microtubule-based motor, so removing microtubules halts its transport. (Choice C) is incorrect: this reflects the misconception that dynein uses actin; dynein is also a microtubule-based motor, so its transport stops when microtubules are gone. (Choice D) is incorrect: this assumes all motor proteins share a single track type, but myosin runs on actin rather than microtubules, so at least one motor''s cargo keeps moving. This is a Knowledge of Scientific Concepts and Principles question because you must recall which cytoskeletal filament each class of motor protein uses as its track.', 'easy', '1A', 'Structure and Function of Proteins and Their Constituent Amino Acids', 'biochemistry', 1, 60)
  RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
  SELECT id, 'B', 'misconception', 'wrong motor-track pairing: assigns the actin track to a microtubule motor (kinesin)' FROM q
  UNION ALL
  SELECT id, 'C', 'misconception', 'wrong motor-track pairing: assigns the actin track to a microtubule motor (dynein)' FROM q
  UNION ALL
  SELECT id, 'D', 'misconception', 'overgeneralization that all motors share one track type, ignoring that myosin uses actin' FROM q;

-- Q3 [Motor Proteins] medium skill2 ans=A
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES ('bio_biochem', 'Non-enzymatic Protein Function and Protein Analysis', 'Motor Proteins', 'A researcher studies vesicle transport driven by a microtubule-based motor protein in a living cell. She introduces a metabolic poison that rapidly blocks ATP regeneration, and cytoplasmic ATP falls to a negligible level while all motor proteins and filaments remain structurally intact. Which outcome for the motor-driven transport of the vesicle is best predicted by the mechanism of this class of proteins?', '[{"label": "A", "text": "Directed transport of the vesicle halts because the motor can no longer complete the conformational cycle that generates a power stroke."}, {"label": "B", "text": "Directed transport of the vesicle continues at a reduced speed, powered by the ADP still bound within the motor domain."}, {"label": "C", "text": "The motor immediately releases the filament, and the vesicle drifts away from the track by free diffusion through the cytosol."}, {"label": "D", "text": "The motor reverses direction and carries the vesicle back toward the opposite end of the filament instead."}]'::jsonb, 'A', 'This is a Biochemistry question that falls under the content category ''Structure and Function of Proteins and Their Constituent Amino Acids.'' The answer is A because motor proteins are ATPases in which the free energy released by ATP hydrolysis drives the allosteric conformational changes (the power stroke) that produce directed stepping along a filament, so depleting ATP removes the energy source and directed movement stops. (Choice A) is correct: with ATP hydrolysis abolished, the motor domain cannot cycle through the nucleotide-dependent conformational changes that generate force, so processive stepping and therefore directed cargo transport cease. (Choice B) is incorrect: this reflects the misconception that a single bound ADP can independently power stepping; the motor requires ongoing ATP binding and hydrolysis to cycle, and a static ADP-bound state cannot repeatedly generate power strokes without turnover. (Choice C) is incorrect: this reverses the actual role of the nucleotide, since it is ATP binding (not its absence) that promotes detachment of the motor head from its track; without ATP the head tends to remain bound rather than release and diffuse away. (Choice D) is incorrect: directionality is set by the motor''s structure and its ATP-driven forward-biased cycle, not by the level of ATP, so removing ATP stalls movement rather than flipping its direction. This is a Scientific Reasoning and Problem Solving question because you must apply the principle that motor-protein movement is powered by ATP hydrolysis to predict the consequence of ATP depletion.', 'medium', '1A', 'Structure and Function of Proteins and Their Constituent Amino Acids', 'biochemistry', 2, 75)
  RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
  SELECT id, 'B', 'misconception', 'bound nucleotide alone can power movement without turnover' FROM q
  UNION ALL
  SELECT id, 'C', 'reversed_relationship', 'ATP absence causes detachment when ATP binding actually causes detachment' FROM q
  UNION ALL
  SELECT id, 'D', 'misconception', 'energy depletion reverses directionality rather than stalling it' FROM q;

-- Q4 [Motor Proteins] medium skill2 ans=A
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES ('bio_biochem', 'Non-enzymatic Protein Function and Protein Analysis', 'Motor Proteins', 'In a motor neuron, the microtubules that run the length of the axon are arranged with uniform polarity: their (+) ends point toward the distal axon terminal, and their (−) ends are anchored near the soma beside the nucleus. A researcher tags a nerve-growth-factor receptor complex that has just been endocytosed at the distal terminal, then tracks whether the labeled complex reaches the nucleus (where it normally triggers a change in gene transcription). Which single manipulation would most specifically abolish arrival of the labeled complex at the nucleus while leaving the outward delivery of newly made vesicles to the terminal intact?', '[{"label": "A", "text": "Selectively inhibiting the dynein motor associated with the labeled complex"}, {"label": "B", "text": "Selectively inhibiting the kinesin motor associated with the labeled complex"}, {"label": "C", "text": "Depolymerizing tubulin subunits only at the microtubule (+) ends"}, {"label": "D", "text": "Blocking ATP hydrolysis in every motor protein throughout the axon"}]'::jsonb, 'A', 'This is a Biochemistry question that falls under the content category ''Structure and Function of Proteins and Their Constituent Amino Acids.'' The answer is A because a complex endocytosed at the terminal must travel back toward the (−) ends anchored near the nucleus, and dynein is the motor that hauls cargo toward the (−) end. (Choice A) is correct: because microtubule (−) ends sit near the soma/nucleus, movement from the terminal back to the nucleus is (−)-end-directed transport, and the textbook states dynein "moves it to the (-) end"; disabling this dynein specifically stops the retrograde trip without affecting outward, (+)-end-directed vesicle delivery driven by a different motor. (Choice B) is incorrect: this reverses the two motors'' directions—kinesin "moves cargo towards the (+) end" (toward the terminal), so inhibiting kinesin would impair the outward delivery that the question requires to stay intact, not the inward trip to the nucleus. (Choice C) is incorrect: this misreads the geometry—the (+) ends are at the distal terminal, far from the nucleus, so trimming (+) ends would not selectively block a cargo moving toward the (−) ends near the soma, and it also assumes track shortening rather than loss of directional transport. (Choice D) is incorrect: both dynein and kinesin use \(\text{ATP}\) hydrolysis to step along microtubules, so a global \(\text{ATP}\)-hydrolysis block would halt outward vesicle delivery too, violating the requirement that outward transport remain intact; it is not the most specific manipulation. This is a Scientific Reasoning and Problem Solving question because you must apply the rule that dynein carries cargo toward the microtubule (−) end and combine it with the given axonal polarity to predict which motor''s loss selectively blocks transport toward the nucleus.', 'medium', '1A', 'Structure and Function of Proteins and Their Constituent Amino Acids', 'biochemistry', 2, 90)
  RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
  SELECT id, 'B', 'reversed_relationship', 'swaps the directional roles of dynein and kinesin' FROM q
  UNION ALL
  SELECT id, 'C', 'misconception', 'misplaces microtubule polarity/anchoring relative to the nucleus' FROM q
  UNION ALL
  SELECT id, 'D', 'partial_truth', 'true that motors use ATP but the manipulation is non-specific and hits outward transport too' FROM q;

-- Q5 [Motor Proteins] easy skill1 ans=A
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES ('bio_biochem', 'Non-enzymatic Protein Function and Protein Analysis', 'Motor Proteins', 'During mitosis, a cell relies on kinesin motor proteins to move and position spindle microtubules so that replicated chromosomes can be arranged and pulled toward the cell''s poles. A researcher engineers a spindle kinesin whose motor head can still bind ATP and still attach to a microtubule, but a point mutation blocks the motor head from hydrolyzing the bound ATP. When this mutant kinesin is expressed in dividing cells, what is the most likely direct consequence for the motor''s activity on the spindle microtubules?', '[{"label": "A", "text": "The motor stalls on the microtubule and fails to generate the directed movement needed to reposition it."}, {"label": "B", "text": "The motor moves normally along the microtubule because ATP binding alone drives its stepping."}, {"label": "C", "text": "The motor reverses course and now steps toward the microtubule''s minus end instead."}, {"label": "D", "text": "The motor moves normally because it draws its energy from the microtubule''s structural polarity."}]'::jsonb, 'A', 'This is a Biochemistry question that falls under the content category ''Structure and Function of Proteins and Their Constituent Amino Acids.'' The answer is A because kinesin''s directed stepping along a microtubule is powered by ATP hydrolysis, so a motor that can bind but not hydrolyze ATP cannot undergo the conformational changes needed to move and stalls. (Choice A) is correct: the textbook states that "force generation by both classes of proteins involves ATP hydrolysis and allosteric shifts in the orientation of the motor domains so that the proteins are thought to ''step'' progressively down the microtubule," so blocking hydrolysis abolishes directed movement even though ATP is bound. (Choice B) is incorrect: this reflects the misconception that nucleotide binding alone is sufficient for motility, but the text specifies that hydrolysis of ATP—not merely binding—drives the allosteric shifts that produce stepping. (Choice C) is incorrect: this reflects the misconception that kinesin''s directionality can flip; the text states "kinesin itself moves towards the plus end of microtubules," and directionality is a fixed structural property, not something a hydrolysis-blocking mutation reverses. (Choice D) is incorrect: this confuses the role of microtubule polarity, which determines the direction of travel, with the source of energy; the text is explicit that motion requires ATP hydrolysis, so polarity cannot substitute as an energy source. This is a Knowledge of Scientific Concepts and Principles question because you must recall that kinesin motor proteins convert the chemical energy of ATP hydrolysis into directed, plus-end movement along microtubules.', 'easy', '1A', 'Structure and Function of Proteins and Their Constituent Amino Acids', 'biochemistry', 1, 75)
  RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
  SELECT id, 'B', 'misconception', 'nucleotide binding alone drives motor stepping' FROM q
  UNION ALL
  SELECT id, 'C', 'reversed_relationship', 'hydrolysis defect reverses kinesin directionality' FROM q
  UNION ALL
  SELECT id, 'D', 'misconception', 'microtubule polarity serves as the energy source rather than the direction cue' FROM q;

-- Q6 [Binding Proteins] hard skill4 ans=A
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES ('bio_biochem', 'Non-enzymatic Protein Function and Protein Analysis', 'Binding Proteins', 'A researcher measures fractional O2 saturation (Y) versus partial pressure of O2 (\(P_{O_2}\)) for a purified tetrameric globin under two buffer conditions. Both curves are S-shaped, and the two curves are nearly superimposable in steepness (their maximum slopes are equal), but the entire curve for Condition 2 lies to the right of the curve for Condition 1. The \(P_{O_2}\) at which Y = 0.5 is 26 mm Hg in Condition 1 and 40 mm Hg in Condition 2. Which conclusion is best supported by comparing these two data sets?

| Condition | \(P_{O_2}\) at Y = 0.5 | Curve shape |
|-----------|------------------------|-------------|
| 1 | 26 mm Hg | S-shaped |
| 2 | 40 mm Hg | S-shaped |', '[{"label": "A", "text": "Condition 2 lowers the protein''s affinity for O2 while leaving the interaction between binding sites essentially unchanged."}, {"label": "B", "text": "Condition 2 raises the protein''s affinity for O2 while leaving the interaction between binding sites essentially unchanged."}, {"label": "C", "text": "Condition 2 lowers the protein''s affinity for O2 and abolishes the interaction between its binding sites."}, {"label": "D", "text": "Condition 2 leaves the protein''s affinity for O2 unchanged but strengthens the interaction between its binding sites."}]'::jsonb, 'A', 'This is a Biochemistry question that falls under the content category ''Structure and Function of Proteins and Their Constituent Amino Acids.'' The answer is A because the \(P_{O_2}\) at half-saturation (\(P_{50}\)) is the operational measure of O2 affinity, so a rise from 26 to 40 mm Hg signals lower affinity, while the unchanged sigmoidal steepness shows the site-to-site interaction (cooperativity) is preserved. (Choice A) is correct: a rightward shift raises \(P_{50}\), and higher \(P_{50}\) means it takes more O2 to reach half-saturation, i.e., decreased affinity; because the curve''s S-shape and maximum slope are unchanged, the degree of interaction between sites is essentially the same — the text notes that raising \(K_D\) (lowering affinity) produces "identical sigmoidal curves shifted progressively to the right." (Choice B) is incorrect: this reverses the direction of the affinity change — a rightward shift to a higher \(P_{50}\) corresponds to decreased, not increased, affinity (higher \(P_{50}\) = weaker binding). (Choice C) is incorrect: this conflates a horizontal shift (an affinity change) with a change in curve shape; abolishing site-to-site interaction would flatten the S-shape toward a hyperbola, but here the steepness is unchanged, so the interaction is not abolished. (Choice D) is incorrect: it wrongly claims affinity is unchanged even though \(P_{50}\) clearly increased, and it attributes the shift to stronger site interaction, which would instead alter the curve''s steepness, not merely translate it rightward. This is a Data-based and Statistical Reasoning question because you must interpret the numeric \(P_{50}\) values and the curve shape to separately assign the horizontal shift to an affinity change and the unchanged steepness to unchanged cooperativity.', 'hard', '1A', 'Structure and Function of Proteins and Their Constituent Amino Acids', 'biochemistry', 4, 100)
  RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
  SELECT id, 'B', 'reversed_relationship', 'Inverts the P50–affinity relationship: reads a rightward shift / higher P50 as increased rather than decreased affinity' FROM q
  UNION ALL
  SELECT id, 'C', 'misconception', 'Conflates a horizontal shift (affinity) with a change in curve shape (cooperativity), concluding site interaction is abolished' FROM q
  UNION ALL
  SELECT id, 'D', 'partial_truth', 'Correctly notes shape governs cooperativity but ignores the clear P50 increase, wrongly calling affinity unchanged' FROM q;

-- Q7 [Binding Proteins] easy skill1 ans=B
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES ('bio_biochem', 'Non-enzymatic Protein Function and Protein Analysis', 'Binding Proteins', 'A researcher studies a cytosolic sensor protein with two distinct regions: one region reversibly grips free \(\text{Ca}^{2+}\) ions, and a separate region docks onto a target kinase. In resting cells the sensor floats free of the kinase, but when intracellular \(\text{Ca}^{2+}\) rises, the \(\text{Ca}^{2+}\)-loaded sensor clamps onto the kinase and the kinase becomes active. The researcher then mutates only the \(\text{Ca}^{2+}\)-gripping region so that it can no longer bind \(\text{Ca}^{2+}\), leaving the kinase-docking region intact. When intracellular \(\text{Ca}^{2+}\) is raised in cells expressing this mutant sensor, what is the most likely outcome for the kinase?', '[{"label": "A", "text": "The kinase becomes constitutively active because losing the \\(\\text{Ca}^{2+}\\) site removes an inhibitory brake on it."}, {"label": "B", "text": "The kinase fails to be activated because the sensor can no longer couple the \\(\\text{Ca}^{2+}\\) signal to it."}, {"label": "C", "text": "The kinase is activated normally because rising \\(\\text{Ca}^{2+}\\) binds the kinase directly without the sensor."}, {"label": "D", "text": "The kinase is permanently switched off because the sensor covalently modifies it during binding."}]'::jsonb, 'B', 'This is a Biochemistry question that falls under the content category ''Structure and Function of Proteins and Their Constituent Amino Acids.'' The answer is B because a binding protein works by physically bringing two molecules together, so a \(\text{Ca}^{2+}\)-binding sensor that can no longer grip \(\text{Ca}^{2+}\) can no longer link the rise in \(\text{Ca}^{2+}\) to the target kinase, and the kinase stays inactive. (Choice A) is incorrect: this is the reversed-relationship misconception that the sensor holds the kinase off; in the scenario the \(\text{Ca}^{2+}\)-loaded sensor turns the kinase on, so abolishing the \(\text{Ca}^{2+}\) site removes activation, not an inhibitory brake. (Choice B) is correct: the sensor''s job is to bring \(\text{Ca}^{2+}\) and the kinase together, so with a dead \(\text{Ca}^{2+}\) site the \(\text{Ca}^{2+}\) signal is never coupled to the kinase and activation fails. (Choice C) is incorrect: this reflects the misconception that the small ligand acts directly on the enzyme and the binding protein is dispensable; the scenario shows the kinase turns on only through the \(\text{Ca}^{2+}\)-loaded sensor, not from \(\text{Ca}^{2+}\) alone. (Choice D) is incorrect: this is the misconception that a binding protein chemically alters its partner; binding proteins associate noncovalently to juxtapose molecules and do not covalently modify the target, and the intact docking region would still bind, not destroy, the kinase. This is a Knowledge of Scientific Concepts and Principles question because you must recall the general function of binding proteins—that they act by bringing molecules together—and read out its consequence in the scenario.', 'easy', '1A', 'Structure and Function of Proteins and Their Constituent Amino Acids', 'biochemistry', 1, 75)
  RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
  SELECT id, 'A', 'reversed_relationship', 'Treats the binding protein as an inhibitor, so removing its ligand site is assumed to release the target rather than fail to activate it.' FROM q
  UNION ALL
  SELECT id, 'C', 'misconception', 'Believes the small ligand acts directly on the target enzyme and the binding protein is a dispensable carrier.' FROM q
  UNION ALL
  SELECT id, 'D', 'misconception', 'Assumes a binding protein covalently modifies its partner rather than associating noncovalently to bring molecules together.' FROM q;

-- Q8 [Immunoglobulins] medium skill1 ans=A
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES ('bio_biochem', 'Non-enzymatic Protein Function and Protein Analysis', 'Immunoglobulins', 'A purified antibody migrates as a single ~150 kDa species on non-reducing SDS-PAGE. When the same sample is run with a reducing agent that cleaves disulfide bonds, it resolves into exactly two bands, one at ~50 kDa and one at ~25 kDa, with the ~25 kDa band staining about twice as intensely as would be expected from a single copy. Which conclusion about the antibody''s architecture is best supported by this result?', '[{"label": "A", "text": "The intact molecule is built from two large chains and two small chains that are joined to one another by interchain disulfide bonds."}, {"label": "B", "text": "The intact molecule is a single continuous polypeptide whose internal disulfide bonds are cleaved to release two separate fragments."}, {"label": "C", "text": "The intact molecule is a pair of identical ~75 kDa chains, each of which is internally nicked into a large and a small piece by the reducing agent."}, {"label": "D", "text": "The intact molecule is held together only by noncovalent contacts, and the reducing agent denatures it into two differently sized subunits."}]'::jsonb, 'A', 'This is a Biochemistry question that falls under the content category ''Structure and Function of Proteins and Their Constituent Amino Acids.'' The answer is A because a multimeric protein whose subunits are held together by disulfide bonds separates into its component chains only when a reducing agent cleaves those bonds, and the two band sizes (~50 kDa and ~25 kDa) plus the mass balance (\(2 \times 50 + 2 \times 25 = 150\) kDa) identify two heavy and two light chains cross-linked by interchain disulfides. (Choice A) is correct: the molecule stays intact at ~150 kDa without reduction because covalent disulfide bonds join the chains, and only after those bonds are cleaved do the two heavy (~50 kDa) and two light (~25 kDa) chains appear as separate bands. (Choice B) is incorrect: this reflects the misconception that a single polypeptide is being cut into fragments; a reducing agent breaks disulfide bonds between and within chains but does not hydrolyze peptide bonds, so it cannot fragment one continuous chain, and a monomeric protein held by only intrachain disulfides would not split into two distinct molecular-weight species. (Choice C) is incorrect: this reflects the misconception that the reducing agent cleaves the polypeptide backbone; reduction breaks \(-S-S-\) bonds, not peptide bonds, so it cannot nick a ~75 kDa chain into a ~50 kDa and a ~25 kDa piece, and this scheme also fails to explain why the native form is a covalently linked 150 kDa unit. (Choice D) is incorrect: this reflects the misconception that only noncovalent forces hold the assembly together, but subunits held solely by noncovalent interactions already separate under denaturing SDS conditions with or without a reducing agent, so a species that stays 150 kDa without reduction and splits only upon reduction must be covalently disulfide-linked. This is a Knowledge of Scientific Concepts and Principles question because you must recall that immunoglobulins are built from two heavy and two light chains joined by interchain disulfide bonds and that reducing agents cleave disulfide bonds rather than peptide bonds.', 'medium', '1A', 'Structure and Function of Proteins and Their Constituent Amino Acids', 'biochemistry', 1, 90)
  RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
  SELECT id, 'B', 'misconception', 'single-continuous-chain fragmented by reduction' FROM q
  UNION ALL
  SELECT id, 'C', 'process_step_confusion', 'reducing agent cleaves peptide backbone instead of disulfides' FROM q
  UNION ALL
  SELECT id, 'D', 'misconception', 'subunits held only by noncovalent forces' FROM q;

-- Q9 [Immunoglobulins] medium skill2 ans=A
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES ('bio_biochem', 'Non-enzymatic Protein Function and Protein Analysis', 'Immunoglobulins', 'A researcher incubates a suspension of live bacteria with purified antibodies raised against a surface protein found across the entire bacterial cell wall, so that the intact bacteria become densely coated with bound antibody. The antibodies used lack any ability to recruit or fix serum complement proteins. When these antibody-coated bacteria are then added to a culture of macrophages, the macrophages clear the bacteria from the medium far more rapidly than they clear an identical suspension of uncoated bacteria. Which change in the macrophages'' handling of the bacteria best accounts for this faster clearance?', '[{"label": "A", "text": "The bound antibody layer is recognized by the macrophages, driving increased engulfment of the bacteria into the cell"}, {"label": "B", "text": "The bound antibody directly ruptures the bacterial cell wall, releasing contents that the macrophages then absorb"}, {"label": "C", "text": "The bound antibody blocks the bacterial surface protein, preventing the bacteria from attaching to the macrophages"}, {"label": "D", "text": "The bound antibody neutralizes secreted bacterial toxins, sparing the macrophages from toxin-induced damage"}]'::jsonb, 'A', 'This is a Biochemistry question that falls under the content category ''Structure and Function of Proteins and Their Constituent Amino Acids.'' The answer is A because an antibody coat on the pathogen surface serves as a recognition tag that phagocytes bind, so coating the bacteria increases their engulfment and clearance. (Choice A) is correct: the variable regions of the bound antibodies attach to the bacterial surface protein while the exposed constant portions form a coat that macrophages recognize and bind, promoting uptake of the whole bacterium into the cell; because the question specifies complement cannot be recruited, the enhanced clearance must come from this direct antibody-mediated recognition rather than from a complement pathway. (Choice B) is incorrect: this reflects the misconception that an antibody destroys a pathogen directly by lysing it; antibody binding is a non-catalytic recognition event and cannot rupture a cell wall on its own, and lysis of an intact wall is not required for a macrophage to engulf the organism. (Choice C) is incorrect: this describes blocking (neutralization) of a surface attachment site, but faster removal here depends on macrophages taking up whole bacteria more efficiently, not on preventing bacterial adhesion; moreover, blocking attachment would tend to reduce contact with the macrophage rather than speed engulfment. (Choice D) is incorrect: this describes neutralization of soluble toxins, a distinct antibody function that protects cells from toxin damage but does nothing to make the bacterial cells themselves easier to engulf and clear, which is what the data show. This is a Scientific Reasoning and Problem Solving question because you must apply the principle that a bound antibody coat acts as a recognition tag for phagocytes to predict which downstream process is enhanced when a pathogen is coated with antibody.', 'medium', '1A', 'Structure and Function of Proteins and Their Constituent Amino Acids', 'biochemistry', 2, 90)
  RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
  SELECT id, 'B', 'misconception', 'antibody kills the pathogen directly by lysing it rather than tagging it for another cell' FROM q
  UNION ALL
  SELECT id, 'C', 'adjacent_fact', 'confuses opsonization with neutralization/blocking of a surface attachment site' FROM q
  UNION ALL
  SELECT id, 'D', 'adjacent_fact', 'confuses opsonization with toxin neutralization, a real but distinct antibody effector function' FROM q;

-- Q10 [Binding Proteins] easy skill1 ans=A
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES ('bio_biochem', 'Non-enzymatic Protein Function and Protein Analysis', 'Binding Proteins', 'A regulatory protein controls transcription of a gene by attaching to a short DNA sequence located in the promoter region upstream of that gene''s coding sequence. In a mutant cell line, this short upstream DNA sequence is scrambled so that its base order is completely changed, while the downstream coding sequence of the gene is left unaltered. Compared with a normal cell, what is the most likely consequence of this mutation for the mutant cell?', '[{"label": "A", "text": "The protein can no longer attach at that site, so its control over the gene''s transcription is lost."}, {"label": "B", "text": "The protein attaches to the site as before, so its control over the gene''s transcription is unchanged."}, {"label": "C", "text": "The protein attaches to the site more tightly, so its control over the gene''s transcription is strengthened."}, {"label": "D", "text": "The protein attaches to the site as before, but the gene now encodes an altered amino acid sequence."}]'::jsonb, 'A', 'This is a Biochemistry question that falls under the content category ''Structure and Function of Proteins and Their Constituent Amino Acids.'' The answer is A because a regulatory DNA-binding protein achieves its effect by attaching to one particular base sequence, so destroying that sequence abolishes the attachment and eliminates the protein''s control over transcription. (Choice A) is correct: the protein''s binding function depends on the identity of the bases at that site, so scrambling the base order removes the site the protein attaches to, and without attachment the protein can no longer regulate the gene. (Choice B) is incorrect: this reflects the misconception that a DNA-binding regulatory protein attaches to DNA non-specifically (the way histones coat DNA regardless of sequence), which would predict unchanged binding after the sequence is scrambled; regulatory proteins of this type instead depend on a particular base sequence. (Choice C) is incorrect: this reverses the relationship, assuming that changing the target sequence would improve binding, whereas altering the bases the protein is matched to weakens or abolishes—not strengthens—the interaction. (Choice D) is incorrect: this confuses an upstream regulatory site with the coding region; the scrambled sequence lies in the promoter and is not translated, so the encoded amino acid sequence is unaffected even though regulation is disrupted. This is a Knowledge of Scientific Concepts and Principles question because you must recall that a regulatory DNA-binding protein carries out its function by attaching to a specific base sequence, so that its ability to control a gene depends on that sequence being intact.', 'easy', '1A', 'Structure and Function of Proteins and Their Constituent Amino Acids', 'biochemistry', 1, 75)
  RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
  SELECT id, 'B', 'misconception', 'treats a sequence-specific regulatory DNA-binding protein as if it binds DNA non-specifically like a histone' FROM q
  UNION ALL
  SELECT id, 'C', 'reversed_relationship', 'assumes changing the target base sequence strengthens rather than weakens binding' FROM q
  UNION ALL
  SELECT id, 'D', 'process_step_confusion', 'confuses an upstream regulatory/promoter binding site with the translated coding sequence' FROM q;

-- Q11 [Ion Channels] medium skill2 ans=A
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES ('bio_biochem', 'Non-enzymatic Protein Function and Protein Analysis', 'Ion Channels', 'A researcher records single-channel currents from three ion channels, each reconstituted alone in its own membrane patch, under three conditions. Channel X conducts steadily whenever the patch is held at −70 mV with no other manipulation, and its open probability is unchanged by a step to +20 mV or by adding the neurotransmitter acetylcholine. Channel Y stays closed at −70 mV and remains closed when acetylcholine is added, but conducts robustly the instant the patch is stepped to +20 mV. Channel Z stays closed at −70 mV and at +20 mV, and conducts only while acetylcholine is present in the bath. The researcher then engineers a mutant in which the charged residues of one channel''s S4 transmembrane segment are neutralized. For which channel would this specific mutation most likely abolish the channel''s ability to switch from a closed to a conducting state?

Channel X — conducts at −70 mV; unaffected by voltage step or acetylcholine
Channel Y — closed until stepped to +20 mV; unaffected by acetylcholine
Channel Z — closed until acetylcholine is added; unaffected by voltage step', '[{"label": "A", "text": "Channel Y, because its gate is driven by movement of charged residues in response to a change in transmembrane potential"}, {"label": "B", "text": "Channel X, because its constant conductance at rest depends on charged residues sensing the resting transmembrane potential"}, {"label": "C", "text": "Channel Z, because neurotransmitter binding must reposition charged residues before the pore can open to ions"}, {"label": "D", "text": "Channel X, because a leak channel relies on the same charged voltage sensor that gated channels use to open"}]'::jsonb, 'A', 'This is a Biochemistry question that falls under the content category ''Biosignaling.'' The answer is A because Channel Y opens specifically upon depolarization and is indifferent to ligand, marking it as a voltage-gated channel whose gating depends on charged S4 residues that move when the transmembrane potential changes. (Choice A) is correct: Channel Y is closed at rest, ignores acetylcholine, and opens the instant the patch is depolarized to +20 mV, which is the signature of a voltage-gated channel; the S4 segment carries the charged residues whose displacement in the membrane field triggers pore opening, so neutralizing them abolishes voltage-dependent gating. (Choice B) is incorrect: this reflects the misconception that a leak (ungated) channel is voltage-sensitive; Channel X conducts constantly and is voltage-insensitive, so it has no functional voltage sensor to neutralize. (Choice C) is incorrect: this confuses ligand gating with voltage gating; Channel Z is a ligand-gated channel that opens because the neurotransmitter binds an extracellular site and rearranges the pore-lining helices, a mechanism independent of the S4 voltage sensor. (Choice D) is incorrect: it asserts that leak channels share the voltage-sensor machinery of gated channels, but a leak channel is ungated and voltage-insensitive, so removing S4 charges would not change Channel X''s behavior. This is a Scientific Reasoning and Problem Solving question because you must apply the distinct gating mechanisms of ungated, voltage-gated, and ligand-gated channels to predict which channel loses function when the voltage sensor is disrupted.', 'medium', '3B', 'Biosignaling', 'biochemistry', 2, 90)
  RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
  SELECT id, 'B', 'misconception', 'attributes voltage-sensing machinery to an ungated leak channel' FROM q
  UNION ALL
  SELECT id, 'C', 'process_step_confusion', 'conflates ligand-gating mechanism with voltage-sensor movement' FROM q
  UNION ALL
  SELECT id, 'D', 'misconception', 'claims leak channels share the S4 voltage sensor of gated channels' FROM q;

-- Q12 [Ion Channels] medium skill2 ans=A
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES ('bio_biochem', 'Non-enzymatic Protein Function and Protein Analysis', 'Ion Channels', 'A researcher studies a neuron whose action potentials depend on a voltage-gated Na⁺ channel. Under normal conditions, the channel''s pore opens only transiently after the membrane reaches a depolarizing threshold, then the cell restores its resting potential of about −70 mV. The researcher then applies a toxin that locks the pore in its ion-conducting configuration and clamps it there independent of the transmembrane potential. Compared with an untreated neuron immediately after a single stimulus, what is the most likely consequence of the toxin in the treated neuron?', '[{"label": "A", "text": "The membrane remains depolarized because inward Na⁺ flow persists even after the potential would normally have reset"}, {"label": "B", "text": "The membrane hyperpolarizes below −70 mV because the trapped channel now conducts K⁺ outward instead of Na⁺ inward"}, {"label": "C", "text": "The resting potential is unchanged because a channel held open cannot conduct any ions until the voltage sensor moves again"}, {"label": "D", "text": "The threshold for firing rises because the open channel prevents the membrane from ever reaching a depolarizing potential"}]'::jsonb, 'A', 'This is a Biochemistry question that falls under the content category ''Biosignaling.'' The answer is A because a voltage-gated Na⁺ channel normally opens only transiently upon depolarization and then closes so the cell can restore its resting potential, so a toxin that clamps the pore open regardless of voltage allows Na⁺ to keep flowing inward and holds the membrane in a depolarized state. (Choice A) is correct: because Na⁺ influx normally depolarizes the neuron and the channel must close for the membrane to return to about \(-70\ \text{mV}\), a pore locked open lets inward Na⁺ current persist, so the membrane stays depolarized instead of resetting. (Choice B) is incorrect: this reflects the misconception that a Na⁺ channel can switch its selectivity to conduct K⁺; the channel''s selectivity filter passes Na⁺ inward and holding the pore open does not reverse the ion or the direction of current, so the cell does not hyperpolarize. (Choice C) is incorrect: this reverses cause and effect by assuming an open channel is non-conducting until the voltage sensor moves; the open (ion-conducting) state is precisely when Na⁺ crosses the pore, so a clamped-open channel conducts continuously rather than being silent. (Choice D) is incorrect: this confuses opening the pore with blocking the pore; a channel held open passes depolarizing Na⁺ current and thus keeps the membrane depolarized rather than preventing it from reaching a depolarizing potential. This is a Scientific Reasoning and Problem Solving question because you must apply the principle that membrane depolarization drives the conformational change opening a voltage-gated channel to predict the outcome when a toxin decouples the channel''s open state from voltage.', 'medium', '3B', 'Biosignaling', 'biochemistry', 2, 90)
  RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
  SELECT id, 'B', 'misconception', 'ion selectivity or current direction can reverse when a channel is trapped open' FROM q
  UNION ALL
  SELECT id, 'C', 'reversed_relationship', 'treats the open conducting state as non-conducting until the voltage sensor moves' FROM q
  UNION ALL
  SELECT id, 'D', 'misconception', 'confuses holding a channel open with blocking the pore' FROM q;

-- Q13 [Ion Channels] easy skill1 ans=A
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES ('bio_biochem', 'Non-enzymatic Protein Function and Protein Analysis', 'Ion Channels', 'A researcher studies a membrane protein in a cultured neuron. In the resting cell, the intracellular \(\text{Na}^+\) concentration is far lower than the extracellular concentration, yet essentially no \(\text{Na}^+\) crosses the membrane through this protein. When the researcher adds a specific neurotransmitter to the extracellular solution, the neurotransmitter binds a site on the protein''s extracellular face and \(\text{Na}^+\) begins to move into the cell. No ATP is consumed during this process. Which change in the protein most directly explains the onset of \(\text{Na}^+\) movement?', '[{"label": "A", "text": "Neurotransmitter binding causes the protein to shift into an open conformation, creating a pore through which \\(\\text{Na}^+\\) diffuses down its gradient."}, {"label": "B", "text": "Neurotransmitter binding covalently attaches \\(\\text{Na}^+\\) to the protein, which then carries the bound ion across to the intracellular side."}, {"label": "C", "text": "Neurotransmitter binding activates the protein to pump \\(\\text{Na}^+\\) inward against its concentration gradient using energy from the neurotransmitter."}, {"label": "D", "text": "Neurotransmitter binding removes the concentration gradient across the membrane, allowing \\(\\text{Na}^+\\) to enter the resting cell freely."}]'::jsonb, 'A', 'This is a Biochemistry question that falls under the content category ''Biosignaling.'' The answer is A because binding of the ligand to the extracellular site triggers a conformational change that opens a central pore, letting \(\text{Na}^+\) diffuse passively down its existing concentration gradient. (Choice A) is correct: the textbook states that a ligand binds the channel protein and "induces a conformational change in the receptor, a ''ligand-gated'' channel," which "would lead to the diffusion of many ions across the membrane (down a concentration gradient)"; because the ion moves down its gradient, no ATP is needed, consistent with the scenario. (Choice B) is incorrect: this reflects the misconception that a channel physically binds and shuttles the permeating ion; channels form a water-filled pore for passive diffusion and do not covalently attach or carry the ion across. (Choice C) is incorrect: this is the active-transport misconception—pumping an ion against its gradient requires an external energy source such as ATP, but the scenario states \(\text{Na}^+\) moves inward (down its gradient) with no ATP consumed, so the channel is not a pump. (Choice D) is incorrect: opening the channel does not abolish the transmembrane concentration gradient; the gradient persists and is in fact the driving force that pushes \(\text{Na}^+\) inward once the pore opens. This is a Knowledge of Scientific Concepts and Principles question because you must recall that ligand binding to a ligand-gated channel opens a pore permitting passive ion diffusion down the gradient.', 'easy', '3B', 'Biosignaling', 'biochemistry', 1, 75)
  RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
  SELECT id, 'B', 'misconception', 'channel_carries_ion' FROM q
  UNION ALL
  SELECT id, 'C', 'misconception', 'channel_is_active_pump' FROM q
  UNION ALL
  SELECT id, 'D', 'misconception', 'gradient_abolished_on_opening' FROM q;

-- Q14 [Ion Channels] easy skill1 ans=A
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES ('bio_biochem', 'Non-enzymatic Protein Function and Protein Analysis', 'Ion Channels', 'A researcher studies a resting cell in which the concentration of K+ is 140 mM inside and 5 mM outside. A membrane protein opens to form a continuous aqueous pore, and K+ begins to move through it. Adding a chemical that halts all ATP production in the cell has no effect on this K+ movement. Which statement best accounts for the observed behavior of this protein?', '[{"label": "A", "text": "It moves K+ out of the cell, and this movement continues without any cellular energy input"}, {"label": "B", "text": "It moves K+ into the cell, and this movement continues without any cellular energy input"}, {"label": "C", "text": "It moves K+ out of the cell, and this movement stops once cellular energy input is blocked"}, {"label": "D", "text": "It moves K+ into the cell, and this movement stops once cellular energy input is blocked"}]'::jsonb, 'A', 'This is a Biochemistry question that falls under the content category ''Biosignaling.'' The answer is A because an ion channel mediates facilitated diffusion, a passive process in which ions flow spontaneously down their concentration gradient (here, from 140 mM inside to 5 mM outside, so K+ exits the cell) without any input of cellular energy such as ATP. (Choice A) is correct: K+ is more concentrated inside than outside, so the favored direction of diffusion is outward, and because channel-mediated facilitated diffusion is passive and requires no energy source, blocking ATP does not stop it. (Choice B) is incorrect: it reflects the misconception that transport occurs up the gradient (into the cell against the higher internal concentration); facilitated diffusion always proceeds down the gradient, and here K+ is higher inside, so net flow is outward. (Choice C) is incorrect: it correctly identifies the outward direction but reflects the misconception that channel transport requires ATP; the passivity of facilitated diffusion is precisely what the ATP-blocking observation confirms. (Choice D) is incorrect: it combines both errors, reversing the gradient direction and wrongly attributing an ATP requirement, which describes active transport rather than a channel. This is a Knowledge of Scientific Concepts and Principles question because you must recall that ion channels carry out passive facilitated diffusion down the electrochemical gradient without energy input, distinguishing it from active transport.', 'easy', '3B', 'Biosignaling', 'biochemistry', 1, 75)
  RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
  SELECT id, 'B', 'reversed_relationship', 'transport-runs-up-the-gradient' FROM q
  UNION ALL
  SELECT id, 'C', 'misconception', 'channel-transport-requires-ATP' FROM q
  UNION ALL
  SELECT id, 'D', 'misconception', 'conflates-channel-with-active-transport' FROM q;

-- Q15 [Receptor Enzymes] medium skill1 ans=A
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES ('bio_biochem', 'Non-enzymatic Protein Function and Protein Analysis', 'Receptor Enzymes', 'A receptor tyrosine kinase spans the plasma membrane once, with its ligand-binding region facing the extracellular space and its catalytic region in the cytoplasm. To probe how this receptor is switched on, an investigator treats cells with a bivalent artificial crosslinker that clamps two receptor monomers together in the membrane. Crucially, this is done in a ligand-free medium, so no natural ligand is present. Compared with untreated cells in the same ligand-free medium, what is the most likely effect on the receptor''s intracellular catalytic activity?', '[{"label": "A", "text": "Intracellular kinase activity is switched on, because forcing the monomers together reproduces the activating step normally caused by ligand binding."}, {"label": "B", "text": "Intracellular kinase activity stays off, because catalysis is triggered only when a ligand physically occupies the extracellular binding site."}, {"label": "C", "text": "Intracellular kinase activity is switched on, but only after the crosslinker itself is transported inward and phosphorylated as the enzyme''s substrate."}, {"label": "D", "text": "Intracellular kinase activity stays off, but a soluble second messenger is instead released by an associated G protein at the membrane."}]'::jsonb, 'A', 'This is a Biochemistry question that falls under the content category ''Biosignaling.'' The answer is A because, for a receptor tyrosine kinase, ligand binding acts by driving two monomers together into a dimer, and it is this dimerization that activates the cytoplasmic kinase domain (leading to autophosphorylation of the partner using ATP); artificially clamping two monomers together therefore switches on the intracellular catalytic activity even without ligand. (Choice A) is correct: the activating event is monomer dimerization, so any means of forcing two monomers together—including a crosslinker in ligand-free medium—reproduces the activation the ligand normally causes. (Choice B) is incorrect: it reflects the misconception that continuous occupancy of the extracellular site is what directly turns on catalysis, whereas the mechanistic role of ligand binding is to promote dimerization, which the crosslinker supplies independently. (Choice C) is incorrect: it reflects the misconception that the extracellular signal molecule is itself the enzyme''s phosphoacceptor substrate; the kinase phosphorylates tyrosine residues on the partner receptor (autophosphorylation), and the crosslinker is not imported or phosphorylated. (Choice D) is incorrect: it confuses the receptor-enzyme mechanism with the G-protein-coupled receptor pathway, in which a G protein and downstream enzyme generate a diffusible second messenger; a receptor tyrosine kinase has intrinsic catalytic activity and does not act through an associated G protein. This is a Knowledge of Scientific Concepts and Principles question because you must recall that a catalytic (enzyme-linked) receptor''s intracellular enzymatic activity is triggered by ligand-induced dimerization rather than by mere occupancy of the binding site or by a G-protein-generated second messenger.', 'medium', '3B', 'Biosignaling', 'biochemistry', 1, 90)
  RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
  SELECT id, 'B', 'misconception', 'ligand-occupancy-directly-activates-catalysis' FROM q
  UNION ALL
  SELECT id, 'C', 'misconception', 'extracellular-ligand-is-the-enzyme-substrate' FROM q
  UNION ALL
  SELECT id, 'D', 'reversed_relationship', 'confuses-receptor-tyrosine-kinase-with-GPCR-second-messenger-pathway' FROM q;

-- Q16 [Receptor Enzymes] hard skill2 ans=A
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES ('bio_biochem', 'Non-enzymatic Protein Function and Protein Analysis', 'Receptor Enzymes', 'A single-pass transmembrane receptor enzyme normally works as follows: an extracellular growth factor binds the receptor, the receptor pairs into a dimer, and this triggers a conformational change that repositions the intracellular catalytic (tyrosine kinase) domains so they phosphorylate each other, launching a downstream cascade. A researcher engineers a point mutation in the region that transmits the conformational change from the ligand-binding module to the catalytic domain. In cells expressing the mutant, radiolabeled growth factor binds the receptor with wild-type affinity and the receptors still form dimers, but no downstream cascade activity is detected. When the purified mutant catalytic domain is supplied with ATP and a peptide substrate in a test tube, it phosphorylates the substrate at the normal rate. Which statement best accounts for the loss of downstream signaling in the intact mutant receptor?', '[{"label": "A", "text": "Ligand binding and dimerization occur, but the conformational change that switches on the catalytic domains is never transmitted, so intracellular autophosphorylation and the downstream cascade fail to initiate."}, {"label": "B", "text": "Because the isolated catalytic domain is fully active, the mutant receptor signals constitutively in the cell and its output is simply masked by feedback inhibition of the downstream cascade."}, {"label": "C", "text": "The mutation lowers the receptor''s affinity for the growth factor, so too little ligand stays bound to hold the dimer together long enough for the catalytic domains to fire."}, {"label": "D", "text": "The mutation blocks ATP from reaching the catalytic domains, so even a correctly positioned kinase cannot transfer phosphate to its substrate in the cell."}]'::jsonb, 'A', 'This is a Biochemistry question that falls under the content category ''Biosignaling.'' The answer is A because the mutation lies in the segment that couples ligand binding to the catalytic domain, so binding and dimerization still occur but the conformational change that activates the kinase never reaches it, leaving autophosphorylation and the downstream cascade unfired. (Choice A) is correct: for a receptor enzyme, ligand binding must induce a conformational change that repositions and activates the intracellular catalytic domain; a mutation that severs this coupling leaves binding and dimerization intact (consistent with the wild-type affinity and preserved dimer formation) yet prevents the catalytic domains from being switched on, so no intracellular autophosphorylation and no downstream signaling occur, even though the isolated domain is catalytically competent. (Choice B) is incorrect: this reflects the misconception that intrinsic catalytic competence of the isolated domain equals signaling in the cell, but the data show no downstream activity, and there is no evidence of constitutive firing being masked; the domain is active in a test tube only because it is no longer waiting on the conformational switch. (Choice C) is incorrect: this contradicts the stated data, which show wild-type ligand affinity and intact dimer formation, so reduced binding cannot be the cause; it confuses a coupling defect with an affinity defect. (Choice D) is incorrect: an ATP-access block is ruled out because the purified mutant catalytic domain phosphorylates substrate at the normal rate when given ATP, so the catalytic machinery and ATP handling are intact; the lesion is in signal transmission, not the active site. This is a Scientific Reasoning and Problem Solving question because you must apply the principle that a receptor enzyme requires ligand-induced conformational change to activate its catalytic domain and use the binding, dimerization, and in vitro activity data to localize the defect to signal transmission rather than to binding or catalysis.', 'hard', '3B', 'Biosignaling', 'biochemistry', 2, 105)
  RETURNING id
)
