-- Q19 [G Protein-Coupled Receptors] medium skill2 ans=A
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES ('bio_biochem', 'Non-enzymatic Protein Function and Protein Analysis', 'G Protein-Coupled Receptors', 'A researcher studying a hormone-responsive cell line adds a non-hydrolyzable analog of GTP directly into the cytoplasm, where it loads onto the α subunit of the stimulatory heterotrimeric G protein that couples to a particular receptor. No hormone is added to the medium. Compared with untreated cells, what is the most likely effect on intracellular cyclic AMP (cAMP) concentration in the treated cells?', '[{"label": "A", "text": "cAMP rises and remains persistently elevated relative to baseline."}, {"label": "B", "text": "cAMP falls and remains persistently below baseline."}, {"label": "C", "text": "cAMP is unchanged because no hormone bound the receptor."}, {"label": "D", "text": "cAMP rises briefly and then returns to its original baseline."}]'::jsonb, 'A', 'This is a Biochemistry question that falls under the content category ''Biosignaling.'' The answer is A because loading the stimulatory Gα subunit with a GTP analog that cannot be hydrolyzed locks Gα in its GTP-bound active conformation, which continuously stimulates adenylate cyclase and drives sustained production of cAMP from ATP. (Choice A) is correct: A Gα subunit is switched ON when GTP is bound and OFF when GDP is bound; the textbook states "The GTP-bound form is active, while the GDP form is inactive" and that preventing GTP cleavage leaves the protein "continually activated." Because this Gα is stimulatory, its active state persistently activates adenylate cyclase, so cAMP rises and stays high—and it does so without hormone, because the analog bypasses the receptor step by directly loading the α subunit. (Choice B) is incorrect: this reverses the sign of the pathway (the stimulatory/inhibitory relationship), treating a locked-active stimulatory Gα as if it suppressed cyclase; an active stimulatory Gα raises, not lowers, cAMP. (Choice C) is incorrect: this misconception assumes the receptor must be occupied for signaling to occur, but the analog loads Gα directly downstream of the receptor, so the cascade proceeds even with no ligand bound. (Choice D) is incorrect: a transient-then-baseline response is what normal signaling looks like when Gα hydrolyzes its GTP to GDP and shuts itself off; using a non-hydrolyzable analog abolishes that intrinsic termination step, so the response does not return to baseline. This is a Scientific Reasoning and Problem Solving question because you must apply the rule that GTP-bound Gα is the active state, combined with the stimulatory Gα–adenylate cyclase–cAMP relationship, to predict the direction and persistence of the cAMP change in a novel experimental manipulation.', 'medium', '3B', 'Biosignaling', 'biochemistry', 2, 85)
  RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
  SELECT id, 'B', 'reversed_relationship', 'Treats a locked-active stimulatory Gα as if it inhibited adenylate cyclase, reversing the stimulatory relationship and predicting a decrease in cAMP.' FROM q
  UNION ALL
  SELECT id, 'C', 'misconception', 'Believes signaling cannot proceed unless the receptor is occupied by ligand, missing that the analog loads Gα directly downstream of the receptor.' FROM q
  UNION ALL
  SELECT id, 'D', 'process_step_confusion', 'Assumes intrinsic GTP hydrolysis still terminates the signal, not recognizing that a non-hydrolyzable analog abolishes the OFF switch and prevents return to baseline.' FROM q;

-- Q20 [G Protein-Coupled Receptors] hard skill2 ans=A
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES ('bio_biochem', 'Non-enzymatic Protein Function and Protein Analysis', 'G Protein-Coupled Receptors', 'A researcher applies an experimental agonist to cultured cardiomyocytes and measures a rapid, dose-dependent fall in intracellular cyclic AMP together with reduced phosphorylation of protein kinase A substrates. The agonist acts exclusively at a single seven-transmembrane receptor and has no effect on the catalytic activity of adenylate cyclase when the enzyme is assayed in isolation. In a second experiment, the same cells are treated simultaneously with this agonist and with epinephrine, a β-adrenergic agonist that alone drives a large rise in cyclic AMP. Compared with epinephrine alone, what is the most likely effect of adding the experimental agonist, and what does the first result reveal about the receptor''s coupling?', '[{"label": "A", "text": "The rise in cyclic AMP is blunted, because the receptor couples to a G protein whose active α subunit suppresses adenylate cyclase, opposing the β-adrenergic effect."}, {"label": "B", "text": "The rise in cyclic AMP is amplified, because the receptor couples to a G protein whose active α subunit stimulates adenylate cyclase, adding to the β-adrenergic effect."}, {"label": "C", "text": "The rise in cyclic AMP is unchanged, because the receptor acts only through the βγ subunits and cannot influence adenylate cyclase output."}, {"label": "D", "text": "The rise in cyclic AMP is abolished, because the receptor directly hydrolyzes cyclic AMP to 5′-AMP through an intrinsic phosphodiesterase domain."}]'::jsonb, 'A', 'This is a Biochemistry question that falls under the content category ''Biosignaling.'' The answer is A because a fall in cyclic AMP that requires an intact seven-transmembrane receptor (the enzyme is unaffected when assayed alone) indicates the receptor couples to an inhibitory G protein whose active α subunit lowers adenylate cyclase output, so co-application must partially oppose the stimulatory β-adrenergic (Gs) response and blunt the cyclic AMP rise. (Choice A) is correct: the drop in cyclic AMP and PKA-substrate phosphorylation, occurring only through the receptor, marks coupling to the inhibitory (Gi) class, whose active \(\alpha\) subunit suppresses adenylate cyclase and therefore counteracts the stimulatory receptor when both are engaged. (Choice B) is incorrect: it reverses the sign of the observed effect—an agonist that lowers cyclic AMP cannot be coupled to a stimulatory (Gs) α subunit, so it would oppose, not add to, the β-adrenergic rise (reversed-relationship misconception). (Choice C) is incorrect: it invokes βγ-only signaling to claim no effect on adenylate cyclase, but the measured decrease in cyclic AMP shows the pathway does modulate the enzyme, so predicting "unchanged" ignores the data (partial-truth misconception that βγ signaling excludes cyclase regulation). (Choice D) is incorrect: it attributes an intrinsic phosphodiesterase activity to the receptor itself; GPCRs act through G proteins on effector enzymes and do not themselves hydrolyze cyclic AMP, and this would predict abolition rather than blunting (process-step confusion). This is a Scientific Reasoning and Problem Solving question because you must apply the opposite effects of stimulatory and inhibitory G proteins on adenylate cyclase to infer receptor coupling from a drug''s effect and predict the outcome of combined treatment.', 'hard', '3B', 'Biosignaling', 'biochemistry', 2, 100)
  RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
  SELECT id, 'B', 'reversed_relationship', 'Assigns the stimulatory (Gs) sign to an agonist that clearly lowers cyclic AMP, flipping the direction of the G-protein effect on adenylate cyclase.' FROM q
  UNION ALL
  SELECT id, 'C', 'partial_truth', 'Correctly notes βγ subunits exist and can signal, but wrongly concludes the receptor cannot alter adenylate cyclase output, contradicting the measured cyclic AMP decrease.' FROM q
  UNION ALL
  SELECT id, 'D', 'process_step_confusion', 'Collapses the GPCR→G protein→effector-enzyme cascade into a single step, attributing intrinsic phosphodiesterase (cyclic AMP-hydrolyzing) activity to the receptor itself.' FROM q;

-- Q21 [G Protein-Coupled Receptors] hard skill2 ans=A
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES ('bio_biochem', 'Non-enzymatic Protein Function and Protein Analysis', 'G Protein-Coupled Receptors', 'A vascular smooth muscle cell expresses a $G_q$-coupled receptor for a peptide hormone. When the hormone binds, the cell shows a rapid, transient spike in cytosolic $\mathrm{Ca}^{2+}$ that does not require any $\mathrm{Ca}^{2+}$ in the surrounding medium. A researcher first treats an unstimulated, hormone-free cell of the same type with a pharmacological inhibitor that fully blocks its phospholipase C, and then wants to reproduce the same cytosolic $\mathrm{Ca}^{2+}$ spike using a single intracellular manipulation. Which manipulation is most likely to succeed?', '[{"label": "A", "text": "Microinjecting inositol 1,4,5-trisphosphate directly into the cytosol"}, {"label": "B", "text": "Microinjecting diacylglycerol directly into the cytosol"}, {"label": "C", "text": "Loading the cytosol with a nonhydrolyzable GTP analog that locks the receptor''s G protein in its active state"}, {"label": "D", "text": "Adding a membrane-permeant activator of adenylyl cyclase to raise intracellular cyclic AMP"}]'::jsonb, 'A', 'This is a Biochemistry question that falls under the content category ''Biosignaling.'' The answer is A because the transient $\mathrm{Ca}^{2+}$ spike originates from an internal store (it needs no extracellular $\mathrm{Ca}^{2+}$), and inositol 1,4,5-trisphosphate ($\mathrm{IP}_3$) is the small, water-soluble messenger that diffuses to the endoplasmic reticulum and opens its $\mathrm{Ca}^{2+}$-release channels; because $\mathrm{IP}_3$ acts downstream of phospholipase C, delivering it directly still works even when phospholipase C is inhibited. (Choice A) is correct: the $G_q$ pathway works by phospholipase C cleaving $\mathrm{PIP}_2$ into diacylglycerol and $\mathrm{IP}_3$, and $\mathrm{IP}_3$ is the soluble arm that reaches the ER and releases sequestered $\mathrm{Ca}^{2+}$, so injecting $\mathrm{IP}_3$ bypasses the blocked phospholipase C step and directly triggers the internal-store spike. (Choice B) is incorrect: it reflects the misconception that both cleavage products drive the $\mathrm{Ca}^{2+}$ release; diacylglycerol is lipophilic and stays in the membrane, where it activates protein kinase C rather than opening ER $\mathrm{Ca}^{2+}$ channels, so it does not by itself raise cytosolic $\mathrm{Ca}^{2+}$. (Choice C) is incorrect: locking the G protein "on" activates the pathway only up to phospholipase C, but phospholipase C has been inhibited, so no $\mathrm{PIP}_2$ is cleaved, no $\mathrm{IP}_3$ is generated, and the ER $\mathrm{Ca}^{2+}$ channels are never opened; activating an upstream node cannot restore a step that lies downstream of the block. (Choice D) is incorrect: it confuses the $G_q$/phospholipase C branch with the $G_s$/adenylyl cyclase branch; cyclic AMP is the messenger of a different pathway and does not open the $\mathrm{IP}_3$-gated ER $\mathrm{Ca}^{2+}$ channels, so it would not reproduce this store-derived spike. This is a Scientific Reasoning and Problem Solving question because you must apply the $G_q \rightarrow$ phospholipase C $\rightarrow \mathrm{PIP}_2 \rightarrow \mathrm{IP}_3 + \mathrm{DAG} \rightarrow$ ER $\mathrm{Ca}^{2+}$ release pathway to predict which single node, when the upstream enzyme is blocked, still recreates the internal-store $\mathrm{Ca}^{2+}$ outcome.', 'hard', '3B', 'Biosignaling', 'biochemistry', 2, 110)
  RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
  SELECT id, 'B', 'process_step_confusion', 'Treats both PLC cleavage products (DAG and IP3) as equivalent triggers of ER Ca2+ release, ignoring that only the soluble IP3 arm reaches the ER while lipophilic DAG stays in the membrane to activate PKC' FROM q
  UNION ALL
  SELECT id, 'C', 'partial_truth', 'Correctly identifies the G protein as the upstream activator of the Gq pathway but fails to place the phospholipase C block: activating the G protein cannot generate IP3 when PLC is inhibited, because that manipulation acts upstream of the blocked step rather than delivering the actual messenger' FROM q
  UNION ALL
  SELECT id, 'D', 'adjacent_fact', 'Confuses the Gq/PLC/IP3 second-messenger branch with the Gs/adenylyl cyclase/cAMP branch, applying the wrong second messenger to an IP3-gated store-release event' FROM q;

-- Q22 [G Protein-Coupled Receptors] medium skill2 ans=A
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES ('bio_biochem', 'Non-enzymatic Protein Function and Protein Analysis', 'G Protein-Coupled Receptors', 'A researcher studies a membrane preparation containing a β-adrenergic receptor (a GPCR) and its heterotrimeric G protein. In a control run, adding the agonist epinephrine produces a burst of downstream effector activity. The researcher then engineers a mutant receptor whose extracellular ligand pocket binds epinephrine with normal affinity, but whose cytoplasmic surface can no longer be reshaped when the ligand is bound. Compared with the wild-type receptor, what is the most likely result when epinephrine is added to the mutant preparation?', '[{"label": "A", "text": "Effector activity is abolished, because the receptor cannot acquire high affinity for the G protein needed to switch it to its active state"}, {"label": "B", "text": "Effector activity is unchanged, because agonist binding at the extracellular pocket is by itself sufficient to activate the G protein"}, {"label": "C", "text": "Effector activity is abolished, because epinephrine can no longer reach and bind the extracellular ligand pocket of the receptor"}, {"label": "D", "text": "Effector activity is enhanced, because a rigid cytoplasmic surface holds the G protein permanently in its bound, active state"}]'::jsonb, 'A', 'This is a Biochemistry question that falls under the content category ''Biosignaling.'' The answer is A because a GPCR relays its signal only after ligand binding drives a propagated conformational change that reshapes the cytoplasmic domain, and it is this reshaped surface that gains affinity for and engages the heterotrimeric G protein to switch it to the active (GTP-bound) state. (Choice A) is correct: with the ligand pocket intact but the cytoplasmic surface locked, epinephrine still binds yet the receptor cannot present the high-affinity cytoplasmic surface, so the G protein is never engaged or switched on and effector output falls to zero. (Choice B) is incorrect: it reflects the misconception that extracellular ligand binding directly activates the G protein; in fact the ligand only triggers a conformational change that must be transmitted to the cytoplasmic domain before any G protein interaction can occur. (Choice C) is incorrect: it misreads the mutation, since the stem states the extracellular pocket still binds epinephrine with normal affinity, so ligand binding is not the blocked step. (Choice D) is incorrect: it reverses the mechanism by assuming a rigid receptor stabilizes the active G protein, whereas the active state is reached by an induced conformational change, and a cytoplasmic surface that cannot be reshaped can never generate the active-state interaction at all. This is a Scientific Reasoning and Problem Solving question because you must apply the ordered causal chain of GPCR activation—ligand binding, propagated conformational change, high-affinity engagement of the G protein, and the switch to the active state—to predict the consequence of interrupting one specific step.', 'medium', '3B', 'Biosignaling', 'biochemistry', 2, 90)
  RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
  SELECT id, 'B', 'process_step_confusion', 'Believes extracellular ligand binding directly activates the G protein, skipping the required intracellular conformational-change step' FROM q
  UNION ALL
  SELECT id, 'C', 'misconception', 'Misidentifies the blocked step as ligand binding rather than signal propagation to the cytoplasmic domain' FROM q
  UNION ALL
  SELECT id, 'D', 'reversed_relationship', 'Reverses the mechanism, treating receptor rigidity as activating rather than recognizing that an induced conformational change is required to reach the active state' FROM q;

-- Q23 [Immunoglobulins] hard skill2 ans=A
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES ('bio_biochem', 'Non-enzymatic Protein Function and Protein Analysis', 'Immunoglobulins', 'A researcher purifies a monoclonal antibody whose two identical antigen-binding regions each recognize the same short epitope. She adds this antibody to a clear solution of a small, freely soluble target molecule that happens to display two copies of that epitope on opposite faces of its surface. Over several minutes, the initially clear mixture grows visibly turbid, and a large insoluble network of joined molecules forms and slowly settles to the bottom of the tube. No cells, receptors, or enzymes are present in the tube. Which molecular outcome of antibody binding does this result represent?', '[{"label": "A", "text": "Agglutination, because each bivalent antibody bridges one target molecule to another, and the two-epitope geometry of the target lets the growing complex branch into an insoluble lattice"}, {"label": "B", "text": "Neutralization, because the antibody has occupied the target''s epitope and thereby blocked a functional binding surface, causing the target to fall out of solution"}, {"label": "C", "text": "Opsonization, because the antibody has coated the surface of the target molecules, tagging the resulting complex so that it is taken up and cleared"}, {"label": "D", "text": "Denaturation-driven precipitation, because antibody binding has unfolded the target protein and reduced its solubility, causing it to aggregate nonspecifically"}]'::jsonb, 'A', 'This is a Biochemistry question that falls under the content category ''Structure and Function of Proteins and Their Constituent Amino Acids.'' The answer is A because the outcome you must identify is cross-linking: each antibody carries two identical antigen-binding regions (it is bivalent), and each target molecule displays two spatially separated copies of the matching epitope. That geometry lets one antibody physically join two targets, and because both partners have two attachment points, the network can branch outward in every direction, growing into a large insoluble lattice that scatters light (turbidity) and eventually settles out. The insolubility is a consequence of multivalent binding geometry alone, not of any cell, receptor, enzyme, or unfolding event. (Choice A) is correct: bridging multiple soluble target molecules into a branched insoluble aggregate through multivalent (two-site) antibody binding is the defining mechanical signature of the outcome described, and it is fully explained by the epitope and antibody valence given in the stem. (Choice B) is incorrect: occupying an epitope to block a functional binding surface would prevent the target from engaging some partner, but by itself, single-site occupancy does not join separate molecules together and cannot build a settling network; the stem''s epitope is a surface feature, not stated to be a functional binding site, so blockade does not explain the insoluble lattice. (Choice C) is incorrect: coating a particle to tag it for uptake requires a phagocytic cell to recognize and internalize the coated complex, yet the tube explicitly contains no cells or receptors, so there is nothing to take the complex up; coating alone would not by itself convert a clear solution into a settling aggregate. (Choice D) is incorrect: the antibody binds a defined epitope with high specificity rather than unfolding its target, and the precipitation here is a specific, structured cross-linked lattice, not nonspecific aggregation from a denatured, misfolded protein; nothing in the scenario perturbs the target''s fold. This is a Scientific Reasoning and Problem Solving question because you must apply your knowledge of antibody architecture, specifically that each immunoglobulin bears two identical antigen-binding regions, to the geometry of a two-epitope target and reason that only multivalent cross-linking can produce the branched, settling insoluble network described, rather than matching the outcome to a memorized definition.', 'hard', '1A', 'Structure and Function of Proteins and Their Constituent Amino Acids', 'biochemistry', 2, 105)
  RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
  SELECT id, 'B', 'misconception', 'Treats any antibody-epitope occupancy as neutralization, ignoring that neutralization requires blocking a functional binding surface and does not join separate molecules into a lattice' FROM q
  UNION ALL
  SELECT id, 'C', 'misconception', 'Confuses coating/tagging (opsonization) with cross-linking; overlooks that opsonization requires a phagocytic cell that is explicitly absent' FROM q
  UNION ALL
  SELECT id, 'D', 'reversed_relationship', 'Attributes the insolubility to nonspecific denaturation/unfolding of the target rather than to specific multivalent cross-linking geometry' FROM q;

-- Q24 [Immunoglobulins] medium skill2 ans=A
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES ('bio_biochem', 'Non-enzymatic Protein Function and Protein Analysis', 'Immunoglobulins', 'A purified antibody is a Y-shaped protein built from two identical heavy chains and two identical light chains. Within the assembled protein, the four chains are joined to one another by interchain disulfide bonds together with noncovalent interactions at the chain–chain interfaces; each chain also has intrachain disulfide bonds that stabilize its own fold. A researcher treats a solution of the intact antibody with a chemical reducing agent that selectively cleaves disulfide bonds but leaves peptide bonds intact, and performs the reaction under nondenaturing (nondenaturing buffer, no detergent, physiological temperature) conditions. If the interchain noncovalent interactions on their own are too weak to hold the assembly together once the covalent links are gone, which outcome best describes what happens to the protein?', '[{"label": "A", "text": "The heavy and light chains dissociate from one another, yielding four separate polypeptide chains."}, {"label": "B", "text": "The two light chains are released as free polypeptides while the two heavy chains remain covalently joined to each other."}, {"label": "C", "text": "The protein is cut into short peptide fragments as its backbone is severed at multiple points."}, {"label": "D", "text": "The chains stay associated as one Y-shaped unit but each individual chain loses its folded three-dimensional shape."}]'::jsonb, 'A', 'This is a Biochemistry question that falls under the content category ''Structure and Function of Proteins and Their Constituent Amino Acids.''

The answer is A because the four chains of the antibody are linked to one another exclusively by covalent interchain disulfide bonds plus noncovalent contacts. A reducing agent cleaves disulfide (\(\text{RS-SR}\)) bonds without touching peptide bonds, so it breaks every covalent link between the chains. The stem stipulates that the remaining noncovalent interactions are, on their own, too weak to hold the assembly together; therefore the quaternary structure comes apart and all four polypeptides (two heavy, two light) are released as separate chains. This matches the textbook principle that a multimeric protein whose subunits are held together by disulfide bonds can be resolved into its component subunits by adding a reducing agent.

(Choice A) is correct: cleaving the interchain disulfides removes the only covalent linkage between the chains, and with the noncovalent contacts insufficient to hold them, all four chains dissociate.

(Choice B) is incorrect: this assumes the two heavy chains are joined by something other than disulfide bonds. They are also held to each other by interchain disulfides, so those links are reduced too and the heavy chains separate along with the light chains — not just the light chains.

(Choice C) is incorrect: this confuses disulfide bonds with peptide bonds. The reducing agent cleaves \(\text{S-S}\) bonds but explicitly does not hydrolyze the peptide (amide) backbone, so the primary structure of each chain is preserved and no short fragments are produced.

(Choice D) is incorrect: this conflates interchain disulfides (which stabilize quaternary structure) with the forces that maintain each chain''s fold. Loss of the covalent links between chains does not by itself unfold the individual tertiary structures, and the stem specifies nondenaturing conditions; the chains separate but remain folded rather than staying together while unfolding.

This is a Skill 2 question because it requires applying knowledge of covalent versus noncovalent stabilizing forces to predict the structural consequence of a specific chemical treatment on a protein''s quaternary organization.', 'medium', '1A', 'Structure and Function of Proteins and Their Constituent Amino Acids', 'biochemistry', 2, 90)
  RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
  SELECT id, 'B', 'partial_truth', 'only-a-subset-of-subunits-released' FROM q
  UNION ALL
  SELECT id, 'C', 'misconception', 'reducing-agent-cleaves-peptide-bonds' FROM q
  UNION ALL
  SELECT id, 'D', 'misconception', 'quaternary-loss-equated-with-tertiary-unfolding' FROM q;

